                vertical.append((c, r, end, color))
            r = end

    bar_colors = {b[3] for b in horizontal} | {b[3] for b in vertical}
    markers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] != background and grid[r][c] not in bar_colors]
    if not markers:
        return out
    fill = markers[0][2]
    marker_coords = {(r, c) for r, c, _ in markers}

    # Pair bars on opposite edges. Markers select matching offsets (lanes)
    # in the two bars; each selected lane projects inward from both bars.
    top = [b for b in horizontal if b[0] == 0]
    bottom = [b for b in horizontal if b[0] == h - 1]
    for a in top:
        for b in bottom:
            if a[3] != b[3]:
                continue
            offsets = set()
            for r, c, _ in markers:
                for bar in (a, b):
                    if bar[1] <= c < bar[2]:
                        offsets.add(c - bar[1])
            for off in offsets:
                for bar, inward in ((a, 1), (b, -1)):
                    lane = bar[1] + off
                    if lane >= bar[2]:
                        continue
                    r = bar[0] + inward
                    while 0 <= r < h:
                        if (r, lane) in marker_coords:
                            out[r][lane] = 4
                            break
                        if grid[r][lane] != background:
                            break
                        out[r][lane] = fill
                        r += inward

    left = [b for b in vertical if b[0] == 0]
    right = [b for b in vertical if b[0] == w - 1]
    for a in left:
        for b in right:
            if a[3] != b[3]:
                continue
            offsets = set()
            for r, c, _ in markers:
                for bar in (a, b):
                    if bar[1] <= r < bar[2]:
                        offsets.add(r - bar[1])
            for off in offsets:
                for bar, inward in ((a, 1), (b, -1)):
                    lane = bar[1] + off
                    if lane >= bar[2]:
                        continue
                    c = bar[0] + inward
                    while 0 <= c < w:
                        if (lane, c) in marker_coords:
                            out[lane][c] = 4
                            break
                        if grid[lane][c] != background:
                            break
                        out[lane][c] = fill
                        c += inward

    return out
